// storyboard callbacks (story `code:`)
static void AnimTask_SW_Lift_Step(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    struct Sprite *mon = &gSprites[task->data[0]];
    s16 t = task->data[5]++;
    s16 up = task->data[2], hold = task->data[3], down = task->data[4];

    if (t < up)
        mon->y2 = -task->data[1] * (t + 1) / up;
    else if (t < up + hold)
        mon->y2 = -task->data[1];
    else if (t < up + hold + down)
        mon->y2 = -task->data[1] * (up + hold + down - t - 1) / down;
    else
    {
        mon->y2 = 0;
        DestroyAnimVisualTask(taskId);
    }
}

// Lift a battler off the ground, hold it, drop it.
// args: battler, height (px), up frames, hold frames, drop frames
void AnimTask_SW_Lift(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    task->data[0] = GetAnimBattlerSpriteId(gBattleAnimArgs[0]);
    task->data[1] = gBattleAnimArgs[1];
    task->data[2] = gBattleAnimArgs[2];
    task->data[3] = gBattleAnimArgs[3];
    task->data[4] = gBattleAnimArgs[4];
    task->data[5] = 0;
    task->func = AnimTask_SW_Lift_Step;
}
